  word_count = EXCLUDED.word_count,
  tags = EXCLUDED.tags,
  source_repo = EXCLUDED.source_repo,
  source_license = EXCLUDED.source_license,
  updated_at = NOW();


DELETE FROM public_wordbook_words
WHERE wordbook_id = (
  SELECT id FROM public_wordbooks WHERE slug = 'computer-science-cswl'
);


